#[derive(Copy, Clone)]
pub struct FileBuffer {
    pub data: *mut u8,
    pub allocated_size: usize,
}

// struct FSDevice is a block of 22 function pointers; only its size/alignment
// matters here.
#[repr(C)]
pub struct FsDevice {
    pub ops: [*mut u8; 22],
}

