#[inline]
unsafe fn list_add(el: *mut ListHead, head: *mut ListHead) {
    let next = (*head).next;
    (*head).next = el;
    (*el).prev = head;
    (*el).next = next;
    (*next).prev = el;
}

#[inline]
unsafe fn list_del(el: *mut ListHead) {
    let prev = (*el).prev;
    let next = (*el).next;
    (*prev).next = next;
    (*next).prev = prev;
    (*el).prev = core::ptr::null_mut();
    (*el).next = core::ptr::null_mut();
}

