    list_add(
        core::ptr::addr_of_mut!((*reg).link),
        core::ptr::addr_of_mut!((*fs).inode_cache_list),
    );
    (*fs).inode_cache_size = (*fs).inode_cache_size.wrapping_add((*reg).size as i64);

