const FT_DIR: c_int = 4;
const FT_LNK: c_int = 10;
const TRUE: c_int = 1;

// `inode_to_qid` is a static C function with no linker symbol, so its logic is
// reproduced here.
unsafe fn inode_to_qid(qid: *mut FSQID, n: *mut FSINode) {
    let ntype = (*n).type_;
    let qtype: u8 = if ntype == FT_DIR {
        0x80u8
    } else if ntype == FT_LNK {
        0x02u8
    } else {
        0x00u8
    };
    (*qid).type_ = qtype;
    (*qid).version = 0;
    (*qid).path = (*n).inode_num;
}

