// private port of the static C function fs_open_end()
unsafe fn open_end(oi: *mut FSOpenInfo) {
    if (*oi).open_type == FS_OPEN_WGET_ARCHIVE_FILE {
        let el: *mut ListHead = core::ptr::addr_of_mut!((*oi).archive_link);
        let prev = (*el).prev;
        let next = (*el).next;
        (*prev).next = next;
        (*next).prev = prev;
        (*el).prev = core::ptr::null_mut();
        (*el).next = core::ptr::null_mut();
    }
    if !(*oi).dec_state.is_null() {
        decrypt_file_end((*oi).dec_state);
    }
    free(oi as *mut c_void);
}

// private port of the static C function fs_wget_set_error()
unsafe fn wget_set_error(n: *mut FSINode) {
    assert_loading(n);
    let oi = (*n).u_reg.open_info;
    (*n).u_reg.state = 1; // REG_STATE_UNLOADED
    file_buffer_reset(core::ptr::addr_of_mut!((*n).u_reg._fbuf));
    if !oi.is_null() {
        if let Some(cb) = (*oi).cb {
            cb((*oi).fs, core::ptr::null_mut(), -5, (*oi).opaque);
        }
        open_end(oi);
    }
}

