// ---------------------------------------------------------------------------
// static inline list helpers from the translation unit
// ---------------------------------------------------------------------------
unsafe fn init_list_head(head: *mut ListHead) {
    (*head).prev = head;
    (*head).next = head;
}

unsafe fn __list_add(el: *mut ListHead, prev: *mut ListHead, next: *mut ListHead) {
    (*prev).next = el;
    (*el).prev = prev;
    (*el).next = next;
    (*next).prev = el;
}

unsafe fn list_add(el: *mut ListHead, head: *mut ListHead) {
    __list_add(el, head, (*head).next);
}

unsafe fn list_add_tail(el: *mut ListHead, head: *mut ListHead) {
    __list_add(el, (*head).prev, head);
}

unsafe fn list_del(el: *mut ListHead) {
    let prev = (*el).prev;
    let next = (*el).next;
    (*prev).next = next;
    (*next).prev = prev;
    (*el).prev = core::ptr::null_mut();
    (*el).next = core::ptr::null_mut();
}

unsafe fn list_empty(el: *mut ListHead) -> c_int {
    if (*el).next == el {
        1
    } else {
        0
    }
}

// ---------------------------------------------------------------------------
// container_of support (offsets computed from real allocations)
// ---------------------------------------------------------------------------
fn reg_link_offset() -> usize {
    // offsetof(FSINode, u.reg.link)
    let mut v = core::mem::MaybeUninit::<FSINode>::uninit();
    let p = v.as_mut_ptr();
    unsafe { (core::ptr::addr_of!((*p).u.reg.link) as usize).wrapping_sub(p as usize) }
}

fn archive_link_offset() -> usize {
    // offsetof(FSOpenInfo, archive_link)
    let mut v = core::mem::MaybeUninit::<FSOpenInfo>::uninit();
    let p = v.as_mut_ptr();
    unsafe { (core::ptr::addr_of!((*p).archive_link) as usize).wrapping_sub(p as usize) }
}

