unsafe fn c_strcmp_equal(a: *const c_char, b: *const c_char) -> bool {
    let mut i: usize = 0;
    loop {
        let ca = *a.add(i) as u8;
        let cb = *b.add(i) as u8;
        if ca != cb {
            return false;
        }
        if ca == 0 {
            return true;
        }
        i += 1;
    }
}

unsafe fn find_preload_archive(
    fs: *const FSDeviceMem,
    filename: *const c_char,
) -> *mut PreloadArchive {
    let head = core::ptr::addr_of!((*fs).preload_archive_list) as *mut ListHead;
    let mut el: *mut ListHead = (*head).next;
    while el != head {
        // link is the first member of PreloadArchive (offsetof == 0)
        let pa = el as *mut PreloadArchive;
        if c_strcmp_equal((*pa).name, filename) {
            return pa;
        }
        el = (*el).next;
    }
    core::ptr::null_mut()
}

