#[inline]
unsafe fn dir_entry_name(de: *const FSDirEntry) -> *const c_char {
    (de as *const u8).add(core::mem::offset_of!(FSDirEntry, mark) + 1) as *const c_char
}

unsafe fn inode_search(n: *mut FSINode, name: *const c_char) -> *mut FSDirEntry {
    if (*n).type_ != FT_DIR {
        return core::ptr::null_mut();
    }
    // &n->u.dir.de_list : `dir` is the first member of the union `u`.
    let head: *mut ListHead = (n as *mut u8).add(core::mem::offset_of!(FSINode, u)) as *mut ListHead;
    let mut el: *mut ListHead = (*head).next;
    while el != head {
        let de = (el as *mut u8).sub(core::mem::offset_of!(FSDirEntry, link)) as *mut FSDirEntry;
        if strcmp(dir_entry_name(de), name) == 0 {
            return de;
        }
        el = (*el).next;
    }
    core::ptr::null_mut()
}

unsafe fn inode_search_path1(mut n: *mut FSINode, mut p: *const c_char) -> *mut FSINode {
    let mut name = [0 as c_char; 1024];

    if *p == b'/' as c_char {
        p = p.add(1);
    }
    if *p == 0 {
        return n;
    }
    loop {
        let p1 = strchr(p, b'/' as c_int);
        let len: c_int;
        let next_p: *const c_char;
        if p1.is_null() {
            len = strlen(p) as c_int;
            next_p = core::ptr::null();
        } else {
            len = ((p1 as usize) - (p as usize)) as c_int;
            next_p = (p1 as *const c_char).add(1);
        }
        if len > (1024 - 1) {
            return core::ptr::null_mut();
        }
        if len > 0 {
            memcpy(
                name.as_mut_ptr() as *mut c_void,
                p as *const c_void,
                len as usize,
            );
        }
        name[len as usize] = 0;
        if (*n).type_ != FT_DIR {
            return core::ptr::null_mut();
        }
        let de = inode_search(n, name.as_ptr());
        if de.is_null() {
            return core::ptr::null_mut();
        }
        n = (*de).inode;
        p = next_p;
        if p.is_null() {
            break;
        }
    }
    n
}

