// static inline void list_del(struct list_head *el) from list.h
unsafe fn list_del(el: *mut ListHead) {
    let prev = (*el).prev;
    let next = (*el).next;
    (*prev).next = next;
    (*next).prev = prev;
    (*el).prev = core::ptr::null_mut();
    (*el).next = core::ptr::null_mut();
}

// static int64_t to_blocks(FSDeviceMem *fs, uint64_t size)
unsafe fn to_blocks(fs: *mut FSDeviceMem, size: u64) -> i64 {
    let bs = (*fs).block_size as u64;
    let v = size.wrapping_add(bs).wrapping_sub(1);
    (v >> ((*fs).block_size_log2 as u32)) as i64
}

// static int fs_truncate(FSDevice *fs1, FSINode *n, uint64_t size)
unsafe fn fs_truncate(fs1: *mut c_void, n: *mut FSINode, size: u64) -> c_int {
    let fs = fs1 as *mut FSDeviceMem;
    let reg = core::ptr::addr_of_mut!((*n).u) as *mut FSINodeReg;

    if (*n).r#type != FT_REG {
        return -22;
    }
    // (size > UINT64_MAX) can never hold, exactly as in the C original.

    let old_size = (*reg).size as u64;
    let diff: i64 = size.wrapping_sub(old_size) as i64;
    if diff == 0 {
        return 0;
    }
    let diff_blocks: i64 = to_blocks(fs, size).wrapping_sub(to_blocks(fs, old_size));

    match (*reg).state {
        REG_STATE_LOADING => {
            return -5;
        }
        REG_STATE_UNLOADED => {
            if size == 0 {
                (*reg).state = REG_STATE_LOCAL;
            }
        }
        REG_STATE_LOADED | REG_STATE_LOCAL => {
            if diff > 0 {
                let sum: i64 = (*fs).fs_blocks.wrapping_add(diff_blocks);
                if (sum as u64) > (*fs).fs_max_blocks {
                    return -28;
                }
                if size > (*reg).fbuf.allocated_size as u64 {
                    let mut new_allocated_size: usize =
                        (*reg).fbuf.allocated_size.wrapping_mul(5) / 4;
                    if size > new_allocated_size as u64 {
                        new_allocated_size = size as usize;
                    }
                    if file_buffer_resize(&mut (*reg).fbuf, new_allocated_size) < 0 {
                        return -28;
                    }
                }
                file_buffer_set(
                    &mut (*reg).fbuf,
                    (*reg).size,
                    0,
                    diff as usize,
                );
            } else {
                let new_allocated_size: usize = (*reg).fbuf.allocated_size.wrapping_mul(4) / 5;
                if size <= new_allocated_size as u64 {
                    if file_buffer_resize(&mut (*reg).fbuf, new_allocated_size) < 0 {
                        return -28;
                    }
                }
            }

            if (*reg).state == REG_STATE_LOADED {
                list_del(&mut (*reg).link);
                (*fs).inode_cache_size =
                    ((*fs).inode_cache_size as u64).wrapping_sub(old_size as u64) as i64;
                if !((*fs).inode_cache_size >= 0) {
                    __assert_fail(
                        b"fs->inode_cache_size >= 0\0".as_ptr() as *const c_char,
                        b"fs_net.c\0".as_ptr() as *const c_char,
                        1233,
                        b"fs_truncate\0".as_ptr() as *const c_char,
                    );
                }
                (*reg).state = REG_STATE_LOCAL;
            }
        }
        _ => abort(),
    }

    (*fs).fs_blocks = (*fs).fs_blocks.wrapping_add(diff_blocks);
    if !((*fs).fs_blocks >= 0) {
        __assert_fail(
            b"fs->fs_blocks >= 0\0".as_ptr() as *const c_char,
            b"fs_net.c\0".as_ptr() as *const c_char,
            1241,
            b"fs_truncate\0".as_ptr() as *const c_char,
        );
    }
    (*reg).size = size as usize;
    0
}

