// Byte-wise string equality, matching strcmp(...) == 0 semantics.
unsafe fn str_eq(a: *const c_char, b: *const c_char) -> bool {
    let mut i: usize = 0;
    loop {
        let ca = *a.add(i) as u8;
        let cb = *b.add(i) as u8;
        if ca != cb {
            return false;
        }
        if ca == 0 {
            return true;
        }
        i += 1;
    }
}

