// static void inode_to_qid(FSQID *qid, FSINode *n)
unsafe fn inode_to_qid(qid: *mut FSQID, n: *mut FSINode) {
    if (*n).type_ == FT_DIR {
        (*qid).type_ = 0x80;
    } else if (*n).type_ == FT_LNK {
        (*qid).type_ = 0x02;
    } else {
        (*qid).type_ = 0x00;
    }
    (*qid).version = 0;
    (*qid).path = (*n).inode_num;
}

