unsafe fn my_strlen(s: *const c_char) -> usize {
    let mut n: usize = 0;
    if !s.is_null() {
        while *s.add(n) != 0 {
            n = n.wrapping_add(1);
        }
    }
    n
}

// static int64_t to_blocks(FSDeviceMem *fs, uint64_t size)
unsafe fn to_blocks(fs: *mut FSDeviceMem, size: u64) -> i64 {
    let bs = (*fs).block_size as u64;
    let log2 = (*fs).block_size_log2 as u32 & 63;
    size.wrapping_add(bs).wrapping_sub(1).wrapping_shr(log2) as i64
}

// static void list_del(struct list_head *el)
unsafe fn list_del(el: *mut ListHead) {
    let prev = (*el).prev;
    let next = (*el).next;
    (*prev).next = next;
    (*next).prev = prev;
    (*el).prev = core::ptr::null_mut();
    (*el).next = core::ptr::null_mut();
}

// static void inode_dirent_delete_no_decref(FSDevice *fs1, FSINode *n,
//                                           FSDirEntry *de)
unsafe fn inode_dirent_delete_no_decref(
    fs1: *mut FSDevice,
    n: *mut FSINode,
    de: *mut FSDirEntry,
) {
    let fs = fs1 as *mut FSDeviceMem;
    // int dirent_size = sizeof(*de) + strlen(de->name) + 1;
    let dirent_size: c_int = core::mem::size_of::<FSDirEntry>()
        .wrapping_add(my_strlen((&(*de).name) as *const [c_char; 0] as *const c_char))
        .wrapping_add(1) as c_int;

    let new_size: c_int = (*n).u.dir.size.wrapping_sub(dirent_size);

    let delta = to_blocks(fs, new_size as i64 as u64)
        .wrapping_sub(to_blocks(fs, (*n).u.dir.size as i64 as u64));
    (*fs).fs_blocks = (*fs).fs_blocks.wrapping_add(delta);
    (*n).u.dir.size = new_size;

    if (*n).u.dir.size < 0 || (*fs).fs_blocks < 0 {
        // The C code asserts these two conditions; emulate the abort.
        std::process::abort();
    }

    list_del(&mut (*de).link);
    free(de as *mut c_void);
}

