// ---- ported static inline helpers -------------------------------------------

#[inline]
unsafe fn init_list_head(head: *mut ListHead) {
    (*head).prev = head;
    (*head).next = head;
}

#[inline]
unsafe fn __list_add(el: *mut ListHead, prev: *mut ListHead, next: *mut ListHead) {
    (*prev).next = el;
    (*el).prev = prev;
    (*el).next = next;
    (*next).prev = el;
}

#[inline]
unsafe fn list_add(el: *mut ListHead, head: *mut ListHead) {
    __list_add(el, head, (*head).next);
}

#[inline]
unsafe fn list_add_tail(el: *mut ListHead, head: *mut ListHead) {
    __list_add(el, (*head).prev, head);
}

// ---- ported static functions -----------------------------------------------

#[inline]
unsafe fn inode_reg(n: *mut FSINode) -> *mut FSINodeReg {
    core::ptr::addr_of_mut!((*n).u) as *mut FSINodeReg
}

#[inline]
unsafe fn inode_dir(n: *mut FSINode) -> *mut FSINodeDir {
    core::ptr::addr_of_mut!((*n).u) as *mut FSINodeDir
}

unsafe fn to_blocks(fs: *mut FSDeviceMem, size: u64) -> i64 {
    let num = size
        .wrapping_add((*fs).block_size as u64)
        .wrapping_sub(1);
    (num >> ((*fs).block_size_log2 as u32)) as i64
}

unsafe fn inode_incref(_fs: *mut FSDevice, n: *mut FSINode) -> *mut FSINode {
    (*n).refcount = (*n).refcount.wrapping_add(1);
    n
}

unsafe fn inode_update_mtime(_fs: *mut FSDevice, n: *mut FSINode) {
    let mut tv = TimeVal {
        tv_sec: 0,
        tv_usec: 0,
    };
    gettimeofday(core::ptr::addr_of_mut!(tv), core::ptr::null_mut());
    (*n).mtime_sec = tv.tv_sec as u32; // truncating conversion, as in C
    (*n).mtime_nsec = tv.tv_usec.wrapping_mul(1000) as u32;
}

unsafe fn inode_new(
    fs1: *mut FSDevice,
    type_: c_int,
    mode: u32,
    uid: u32,
    gid: u32,
) -> *mut FSINode {
    let fs = fs1 as *mut FSDeviceMem;
    let n: *mut FSINode;

    n = mallocz(core::mem::size_of::<FSINode>()) as *mut FSINode;
    (*n).refcount = 1;
    (*n).open_count = 0;
    (*n).inode_num = (*fs).inode_num_alloc;
    (*fs).inode_num_alloc = (*fs).inode_num_alloc.wrapping_add(1);
    (*n).type_ = type_;
    (*n).mode = mode & 0xfff;
    (*n).uid = uid;
    (*n).gid = gid;

    if type_ == FT_REG {
        file_buffer_init(core::ptr::addr_of_mut!((*inode_reg(n)).fbuf));
    } else if type_ == FT_DIR {
        init_list_head(core::ptr::addr_of_mut!((*inode_dir(n)).de_list));
    }

    list_add(
        core::ptr::addr_of_mut!((*n).link),
        core::ptr::addr_of_mut!((*fs).inode_list),
    );
    (*fs).inode_count = (*fs).inode_count.wrapping_add(1);

    inode_update_mtime(fs1, n);
    (*n).ctime_sec = (*n).mtime_sec;
    (*n).ctime_nsec = (*n).mtime_nsec;

    n
}

unsafe fn inode_dir_add(
    fs1: *mut FSDevice,
    n: *mut FSINode,
    name: *const c_char,
    n1: *mut FSINode,
) -> *mut FSDirEntry {
    let fs = fs1 as *mut FSDeviceMem;
    let de: *mut FSDirEntry;
    let name_len: c_int;
    let dirent_size: c_int;
    let new_size: c_int;

    if (*n).type_ != FT_DIR {
        __assert_fail(
            b"n->type == FT_DIR\0".as_ptr() as *const c_char,
            b"fs_net.c\0".as_ptr() as *const c_char,
            456,
            b"inode_dir_add\0".as_ptr() as *const c_char,
        );
    }

    name_len = strlen(name) as c_int;
    de = mallocz(
        core::mem::size_of::<FSDirEntry>()
            .wrapping_add(name_len as usize)
            .wrapping_add(1),
    ) as *mut FSDirEntry;
    (*de).inode = n1;
    memcpy(
        core::ptr::addr_of_mut!((*de).name) as *mut c_void,
        name as *const c_void,
        name_len as usize + 1,
    );
    dirent_size = core::mem::size_of::<FSDirEntry>() as c_int + name_len + 1;
    let d = inode_dir(n);
    new_size = (*d).size.wrapping_add(dirent_size);
    (*fs).fs_blocks = (*fs).fs_blocks.wrapping_add(
        to_blocks(fs, new_size as u64) - to_blocks(fs, (*d).size as u64),
    );
    (*d).size = new_size;
    list_add_tail(
        core::ptr::addr_of_mut!((*de).link),
        core::ptr::addr_of_mut!((*d).de_list),
    );
    de
}

