// Equivalent of `strcmp(a, b) == 0` for NUL terminated C strings.
unsafe fn c_str_eq(a: *const c_char, b: *const c_char) -> bool {
    let mut i: isize = 0;
    loop {
        let ca = *a.offset(i) as u8;
        let cb = *b.offset(i) as u8;
        if ca != cb {
            return false;
        }
        if ca == 0 {
            return true;
        }
        i += 1;
    }
}

