// static BOOL fs_is_net(FSDevice *fs) { return (fs->fs_end == fs_mem_end); }
// `fs_mem_end` has no linker symbol, so the expected callback address is
// handed in by the caller.
unsafe fn fs_is_net(fs1: *mut FSDevice, fs_mem_end: Option<unsafe extern "C" fn(*mut FSDevice)>) -> BOOL {
    let installed = match (*fs1).fs_end {
        Some(f) => f as usize,
        None => 0usize,
    };
    let expected = match fs_mem_end {
        Some(f) => f as usize,
        None => 0usize,
    };
    if installed == expected {
        1
    } else {
        0
    }
}

