// fs_mem_end is also static, so its address is handed in by the C caller.

#![allow(non_camel_case_types)]

// The FSDevice struct is only ever reached through a pointer; we only need its
// first field (fs_end) at offset 0.
pub type FSDevice = core::ffi::c_void;

type FsEndFn = unsafe extern "C" fn(*mut FSDevice);

#[repr(C)]
pub struct FSDeviceHead {
    pub fs_end: Option<FsEndFn>,
}

// Returns 1 when the device is a net device (fs->fs_end == fs_mem_end), 0 otherwise.
#[no_mangle]
pub extern "C" fn fs_dump_cache_load__part914(
    fs1: *mut FSDevice,
    fs_mem_end: Option<FsEndFn>,
) -> core::ffi::c_int {
    if fs1.is_null() {
        return 0;
    }
    let head = unsafe { &*(fs1 as *const FSDeviceHead) };
    let end_addr = match head.fs_end {
        Some(f) => f as usize,
        None => 0usize,
    };
    let mem_addr = match fs_mem_end {
        Some(f) => f as usize,
        None => 0usize,
    };
    if end_addr == mem_addr {
        1
    } else {
        0
    }
}
