const FT_DIR: c_int = 4;
const FT_BLK: c_int = 6;
const FT_REG: c_int = 8;
const FT_LNK: c_int = 10;

const REG_STATE_LOCAL: c_int = 0;
const REG_STATE_UNLOADED: c_int = 1;

