// static inline BOOL isspace_nolf(int c)
#[inline]
fn isspace_nolf(c: c_int) -> bool {
    c == b' ' as c_int || c == b'\t' as c_int
}

// static inline void init_list_head(struct list_head *head)
#[inline]
unsafe fn init_list_head(head: *mut ListHead) {
    (*head).prev = head;
    (*head).next = head;
}

// static inline void list_add_tail(struct list_head *el, struct list_head *head)
//   == __list_add(el, head->prev, head)
#[inline]
unsafe fn list_add_tail(el: *mut ListHead, head: *mut ListHead) {
    let prev = (*head).prev;
    let next = head;
    (*prev).next = el;
    (*el).prev = prev;
    (*el).next = next;
    (*next).prev = el;
}

// static FSDirEntry *inode_search(FSINode *n, const char *name)
unsafe fn inode_search(n: *mut FSINode, name: *const c_char) -> *mut FSDirEntry {
    if (*n).type_ != FT_DIR {
        return null_mut();
    }
    // u.dir.de_list lives at offset 0 of the union, as does u.reg.
    let head: *mut ListHead = &mut (*n).u as *mut Reg as *mut ListHead;
    let mut el: *mut ListHead = (*head).next;
    while el != head {
        // container_of(el, FSDirEntry, link): link is the first field.
        let de = el as *mut FSDirEntry;
        let de_name: *const c_char = &(*de).name as *const [c_char; 1] as *const c_char;
        if strcmp(de_name, name) == 0 {
            return de;
        }
        el = (*el).next;
    }
    null_mut()
}

