unsafe fn rust_strlen(mut s: *const c_char) -> usize {
    let mut n: usize = 0;
    while *s != 0 {
        s = s.add(1);
        n += 1;
    }
    n
}

unsafe fn rust_strchr(s: *const c_char, c: c_char) -> *const c_char {
    let mut p = s;
    loop {
        if *p == c {
            return p;
        }
        if *p == 0 {
            return null();
        }
        p = p.add(1);
    }
}

unsafe fn rust_strcmp(a: *const c_char, b: *const c_char) -> c_int {
    let mut i: isize = 0;
    loop {
        let ca = *a.offset(i) as u8;
        let cb = *b.offset(i) as u8;
        if ca != cb {
            return ca as c_int - cb as c_int;
        }
        if ca == 0 {
            return 0;
        }
        i += 1;
    }
}

// static FSDirEntry *inode_search(FSINode *n, const char *name)
unsafe fn inode_search(n: *mut FSINode, name: *const c_char) -> *mut FSDirEntry {
    if (*n).type_ != FT_DIR {
        return null_mut();
    }

    let head = addr_of_mut!((*n).u.dir.de_list);
    let mut el = (*head).next;
    while el != head {
        // offsetof(FSDirEntry, link) == 0
        let de = el as *mut FSDirEntry;
        let de_name = (*de).name.as_ptr();
        if rust_strcmp(de_name, name) == 0 {
            return de;
        }
        el = (*el).next;
    }
    null_mut()
}

// static FSINode *inode_search_path1(FSDevice *fs, FSINode *n, const char *path)
unsafe fn inode_search_path1(
    _fs: *mut FSDevice,
    mut n: *mut FSINode,
    path: *const c_char,
) -> *mut FSINode {
    let mut name = [0 as c_char; 1024];

    let mut p = path;
    if *p == b'/' as c_char {
        p = p.add(1);
    }
    if *p == 0 {
        return n;
    }
    loop {
        let slash = rust_strchr(p, b'/' as c_char);
        let len: isize;
        let next: *const c_char;
        if slash.is_null() {
            len = rust_strlen(p) as isize;
            next = null();
        } else {
            len = slash.offset_from(p);
            next = slash.add(1);
        }
        if len as usize > 1023 {
            return null_mut();
        }
        let mut i: isize = 0;
        while i < len {
            *name.as_mut_ptr().offset(i) = *p.offset(i);
            i += 1;
        }
        *name.as_mut_ptr().offset(len) = 0;

        if (*n).type_ != FT_DIR {
            return null_mut();
        }
        let de = inode_search(n, name.as_ptr());
        if de.is_null() {
            return null_mut();
        }
        n = (*de).inode;
        p = next;
        if p.is_null() {
            break;
        }
    }
    n
}

// static FSINode *inode_search_path(FSDevice *fs1, const char *path)
unsafe fn inode_search_path(fs1: *mut FSDevice, path: *const c_char) -> *mut FSINode {
    if fs1.is_null() {
        return null_mut();
    }
    let fs = fs1 as *mut FSDeviceMem;
    inode_search_path1(fs1, (*fs).root_inode, path)
}

