// Local re-implementation of strlen so no libc symbol declaration is needed.
fn c_strlen(s: *const c_char) -> usize {
    let mut n: usize = 0;
    if s.is_null() {
        return 0;
    }
    unsafe {
        while *s.add(n) != 0 {
            n += 1;
        }
    }
    n
}

