unsafe fn inode_search(n: *mut FSINode, name: *const c_char) -> *mut FSDirEntry {
    if (*n).node_type != FT_DIR {
        return core::ptr::null_mut();
    }
    let head: *mut ListHead = core::ptr::addr_of_mut!((*n).u_dir_de_list);
    let mut el: *mut ListHead = (*head).next;
    while el != head {
        // offsetof(FSDirEntry, link) == 0
        let de = el as *mut FSDirEntry;
        if strcmp((*de).name.as_ptr(), name) == 0 {
            return de;
        }
        el = (*el).next;
    }
    core::ptr::null_mut()
}

unsafe fn inode_search_path1(n_start: *mut FSINode, path: *const c_char) -> *mut FSINode {
    let mut name = [0 as c_char; 1024];
    let mut n: *mut FSINode = n_start;
    let mut p: *const c_char = path;

    if *p == b'/' as c_char {
        p = p.add(1);
    }
    if *p == 0 {
        return n;
    }
    loop {
        let mut p1: *mut c_char = strchr(p, b'/' as c_int);
        let len: c_int;
        if p1.is_null() {
            len = strlen(p) as c_int;
        } else {
            len = (p1 as usize).wrapping_sub(p as usize) as c_int;
            p1 = p1.add(1);
        }
        if len > 1023 {
            return core::ptr::null_mut();
        }
        if len > 0 {
            core::ptr::copy_nonoverlapping(p, name.as_mut_ptr(), len as usize);
        }
        name[len as usize] = 0;
        if (*n).node_type != FT_DIR {
            return core::ptr::null_mut();
        }
        let de = inode_search(n, name.as_ptr());
        if de.is_null() {
            return core::ptr::null_mut();
        }
        n = (*de).inode;
        p = p1 as *const c_char;
        if p.is_null() {
            break;
        }
    }
    n
}

