// fs_find_base_url, fs_base_url_decref, inode_search_path, inode_search,
// inode_search_path1, to_blocks, fs_cmd_xhr_on_load).

use core::ffi::{c_char, c_int, c_void};
use core::ptr::null_mut;

// ---------------------------------------------------------------------------
// mirrors of the C data structures
// ---------------------------------------------------------------------------

#[repr(C)]
#[derive(Copy, Clone)]
pub struct ListHead {
    pub prev: *mut ListHead,
    pub next: *mut ListHead,
}

#[repr(C)]
#[derive(Copy, Clone)]
pub struct FSQID {
    pub type_: u8,
    pub version: u32,
    pub path: u64,
}

#[repr(C)]
#[derive(Copy, Clone)]
pub struct AES_KEY {
    pub rd_key: [u32; 60],
    pub rounds: c_int,
}

#[repr(C)]
#[derive(Copy, Clone)]
pub struct FileBuffer {
    pub data: *mut u8,
    pub allocated_size: usize,
}

#[repr(C)]
#[derive(Copy, Clone)]
pub struct FSBaseURL {
    pub link: ListHead,
    pub ref_count: c_int,
    pub base_url_id: *mut c_char,
    pub url: *mut c_char,
    pub user: *mut c_char,
    pub password: *mut c_char,
    pub encrypted: c_int,
    pub aes_state: AES_KEY,
}

#[repr(C)]
#[derive(Copy, Clone)]
pub struct FSINodeReg {
    pub state: c_int,
    pub size: usize,
    pub fbuf: FileBuffer,
    pub base_url: *mut FSBaseURL,
    pub file_id: u64,
    pub link: ListHead,
    pub open_info: *mut c_void,
    pub is_fscmd: c_int,
    pub filename: *mut c_char,
}

#[repr(C)]
#[derive(Copy, Clone)]
pub struct FSINodeDir {
    pub de_list: ListHead,
    pub size: c_int,
}

#[repr(C)]
#[derive(Copy, Clone)]
pub struct FSINodeDev {
    pub major: u32,
    pub minor: u32,
}

#[repr(C)]
#[derive(Copy, Clone)]
pub struct FSINodeSymlink {
    pub name: *mut c_char,
}

#[repr(C)]
#[derive(Copy, Clone)]
pub union FSINodeU {
    pub reg: FSINodeReg,
    pub dir: FSINodeDir,
    pub dev: FSINodeDev,
    pub symlink: FSINodeSymlink,
}

#[repr(C)]
#[derive(Copy, Clone)]
pub struct FSINode {
    pub link: ListHead,
    pub inode_num: u64,
    pub refcount: i32,
    pub open_count: i32,
    pub type_: c_int,
    pub mode: u32,
    pub uid: u32,
    pub gid: u32,
    pub mtime_sec: u32,
    pub ctime_sec: u32,
    pub mtime_nsec: u32,
    pub ctime_nsec: u32,
    pub u: FSINodeU,
}

#[repr(C)]
#[derive(Copy, Clone)]
pub struct FSDirEntry {
    pub link: ListHead,
    pub inode: *mut FSINode,
    pub mark: u8,
    // char name[0];
    pub name: [c_char; 0],
}

#[repr(C)]
#[derive(Copy, Clone)]
pub struct CmdXHRState {
    pub req_fd: *mut FSFile,
    pub root_fd: *mut FSFile,
    pub fd: *mut FSFile,
    pub post_fd: *mut FSFile,
    pub aes_state: AES_KEY,
}

#[repr(C)]
#[derive(Copy, Clone)]
pub struct FSCMDRequest {
    pub type_: c_int,
    pub xhr_state: *mut CmdXHRState,
    pub reply_len: c_int,
    pub reply_buf: [u8; 64],
}

#[repr(C)]
#[derive(Copy, Clone)]
pub struct FSFile {
    pub uid: u32,
    pub inode: *mut FSINode,
    pub is_opened: c_int,
    pub open_flags: u32,
    pub req: *mut FSCMDRequest,
}

#[repr(C)]
pub struct FSDevice {
    pub fs_end: *mut c_void,
    pub fs_delete: Option<unsafe extern "C" fn(*mut FSDevice, *mut FSFile)>,
    pub fs_statfs: *mut c_void,
    pub fs_attach: Option<
        unsafe extern "C" fn(
            *mut FSDevice,
            *mut *mut FSFile,
            *mut FSQID,
            u32,
            *const c_char,
            *const c_char,
        ) -> c_int,
    >,
    pub fs_walk: *mut c_void,
    pub fs_mkdir: *mut c_void,
    pub fs_open: Option<
        unsafe extern "C" fn(
            *mut FSDevice,
            *mut FSQID,
            *mut FSFile,
            u32,
            *mut c_void,
            *mut c_void,
        ) -> c_int,
    >,
    pub fs_create: Option<
        unsafe extern "C" fn(
            *mut FSDevice,
            *mut FSQID,
            *mut FSFile,
            *const c_char,
            u32,
            u32,
            u32,
        ) -> c_int,
    >,
    pub fs_stat: *mut c_void,
    pub fs_setattr: *mut c_void,
    pub fs_close: *mut c_void,
    pub fs_readdir: *mut c_void,
    pub fs_read: *mut c_void,
    pub fs_write: *mut c_void,
    pub fs_link: *mut c_void,
    pub fs_symlink: *mut c_void,
    pub fs_mknod: *mut c_void,
    pub fs_readlink: *mut c_void,
    pub fs_renameat: *mut c_void,
    pub fs_unlinkat: Option<unsafe extern "C" fn(*mut FSDevice, *mut FSFile, *const c_char) -> c_int>,
    pub fs_lock: *mut c_void,
    pub fs_getlock: *mut c_void,
}

// Only the leading part of FSDeviceMem (up to 'import_dir') is accessed.
#[repr(C)]
pub struct FSDeviceMem {
    pub common: FSDevice,
    pub inode_list: ListHead,
    pub inode_count: i64,
    pub inode_limit: u64,
    pub fs_blocks: i64,
    pub fs_max_blocks: u64,
    pub inode_num_alloc: u64,
    pub block_size_log2: c_int,
    pub block_size: u32,
    pub root_inode: *mut FSINode,
    pub inode_cache_list: ListHead,
    pub inode_cache_size: i64,
    pub inode_cache_size_limit: i64,
    pub preload_list: ListHead,
    pub preload_archive_list: ListHead,
    pub base_url_list: ListHead,
    pub import_dir: *mut c_char,
}

