static ASSERT_NET: &[u8] = b"fs_is_net(fs)\0";
static ASSERT_ATTACH: &[u8] = b"!fs->fs_attach(fs, &root_fd, &qid, 0, \"\", \"\")\0";
static ASSERT_CREATE: &[u8] =
    b"!fs->fs_create(fs, &qid, root_fd, \".fscmd_pwd\", P9_O_RDWR | P9_O_TRUNC, 0600, 0)\0";
static FILE_NAME: &[u8] = b"fs_net.c\0";
