static EMPTY: &[u8] = b"\0";
static NAME_PWD: &[u8] = b".fscmd_pwd\0";

#[inline]
unsafe fn assert_fail(assertion: &[u8], line: c_uint) -> ! {
    __assert_fail(
        assertion.as_ptr() as *const c_char,
        FILE_NAME.as_ptr() as *const c_char,
        line,
        FUNC_NAME.as_ptr() as *const c_char,
    )
}

#[inline]
fn must<T>(v: Option<T>) -> T {
    match v {
        Some(f) => f,
        None => std::process::abort(),
    }
}

// fs_net.c lines 2855-2864:
//   assert(fs_is_net(fs));
//   assert(!fs->fs_attach(fs, &root_fd, &qid, 0, "", ""));
//   assert(!fs->fs_create(fs, &qid, root_fd, ".fscmd_pwd",
//                         P9_O_RDWR | P9_O_TRUNC, 0600, 0));
//   fs->fs_write(fs, root_fd, 0, (uint8_t *)pwd, strlen(pwd));
//   fs->fs_delete(fs, root_fd);
// `root_fd` and `qid` live in the C caller: proot_fd/pqid point at them.
// `fs_mem_end_p` is the address of the static C function fs_mem_end, which is
// what the static C helper fs_is_net(fs) compares fs->fs_end against.
#[no_mangle]
pub unsafe extern "C" fn fs_net_set_pwd__part1080(
    fs: *mut FSDevice,
    pwd: *const c_char,
    proot_fd: *mut *mut FSFile,
    pqid: *mut FSQID,
    fs_mem_end_p: Option<FnEnd>,
) {
    // assert(fs_is_net(fs)): fs->fs_end == fs_mem_end
    let is_net = if fs.is_null() {
        false
    } else {
        match (*fs).fs_end {
            Some(f) => (f as usize) == (fs_mem_end_p.map(|p| p as usize).unwrap_or(0)),
            None => fs_mem_end_p.is_none(),
        }
    };
    if !is_net {
        assert_fail(ASSERT_NET, 2858);
    }

    // assert(!fs->fs_attach(fs, &root_fd, &qid, 0, "", ""));
    let attach = must((*fs).fs_attach);
    let r = attach(
        fs,
        proot_fd,
        pqid,
        0,
        EMPTY.as_ptr() as *const c_char,
        EMPTY.as_ptr() as *const c_char,
    );
    if r != 0 {
        assert_fail(ASSERT_ATTACH, 2860);
    }

    // assert(!fs->fs_create(fs, &qid, root_fd, ".fscmd_pwd",
    //                       P9_O_RDWR | P9_O_TRUNC, 0600, 0));
    let create = must((*fs).fs_create);
    let r = create(
        fs,
        pqid,
        *proot_fd,
        NAME_PWD.as_ptr() as *const c_char,
        0x0000_0002u32 | 0x0000_0200u32,
        0o600u32,
        0u32,
    );
    if r != 0 {
        assert_fail(ASSERT_CREATE, 2861);
    }

    // fs->fs_write(fs, root_fd, 0, (uint8_t *)pwd, strlen(pwd));
    let write = must((*fs).fs_write);
    write(
        fs,
        *proot_fd,
        0,
        pwd as *const u8,
        strlen(pwd) as c_int,
    );

    // fs->fs_delete(fs, root_fd);
    let delete = must((*fs).fs_delete);
    delete(fs, *proot_fd);
}
